-- US MD/MBBS (4th Year) clinical case blocks - Clinical Case Integration: Interpretation of labs, imaging, biopsies in context
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'case-labs-imaging' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic case-labs-imaging not found.';
    END IF;

    -- Clear existing MCQs for this topic to avoid duplicates
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

END $$;
COMMIT;
